import React, { useState, useEffect } from 'react';

// 1. Create a Person class
class Person {
  constructor(name, age) {
    this.name = name;
    this.age = age;
  }

  introduce() {
    return `Hello, my name is ${this.name} and I am ${this.age} years old.`;
  }
}

// 2. Create a Student class that extends Person
class Student extends Person {
  constructor(name, age, scores = []) {
    super(name, age);
    this.scores = scores;
  }

  calculateAverage() {
    if (this.scores.length === 0) return 0;
    const total = this.scores.reduce((sum, score) => sum + score, 0);
    return (total / this.scores.length).toFixed(2);
  }

  getStudentInfo() {
    return `${this.introduce()} | Scores: [${this.scores.join(', ')}] | Avg: ${this.calculateAverage()}`;
  }
}

// 3. Use Rest Parameter
const createScores = (...scores) => {
  return scores;
};

export default function App() {
  const initialScores = createScores(8, 9, 10);

  const [student, setStudent] = useState(
    new Student("Alex", 20, initialScores)
  );

  const [inputScore, setInputScore] = useState('');
  const [evaluation, setEvaluation] = useState('Evaluating...');

  // 4. Use Destructuring
  const { name, age, scores } = student;
  const avgScore = student.calculateAverage();

  // 5. Use Spread Operator
  const handleAddScore = (e) => {
    e.preventDefault();
    const parsedScore = parseFloat(inputScore);

    if (isNaN(parsedScore) || parsedScore < 0 || parsedScore > 10) {
      alert("Vui lòng nhập điểm hợp lệ từ 0 đến 10!");
      return;
    }

    const updatedScores = [...scores, parsedScore];
    setStudent(new Student(name, age, updatedScores));
    setInputScore('');
  };

  // 6. Use Array Methods
  const passingScores = scores.filter((s) => s >= 5);
  const formattedScores = scores.map((s) => `${s}đ`);
  const totalScore = scores.reduce((sum, s) => sum + s, 0);

  // 7. Use Promise
  useEffect(() => {
    const evaluatePerformance = (avg) => {
      return new Promise((resolve) => {
        setTimeout(() => {
          if (avg >= 8) {
            resolve("Excellent Student");
          } else {
            resolve("Need Improvement");
          }
        }, 600);
      });
    };

    setEvaluation("Analyzing...");
    evaluatePerformance(parseFloat(avgScore)).then((result) => {
      setEvaluation(result);
    });
  }, [avgScore]);

  return (
    <div style={{ maxWidth: '600px', margin: '30px auto', fontFamily: 'Arial, sans-serif', padding: '20px', border: '1px solid #ddd', borderRadius: '10px' }}>
      <h1 style={{ textAlign: 'center', color: '#2c3e50' }}>Student Management (ES6)</h1>

      {/* 1 & 2. Class Method & Introduce */}
      <div style={{ background: '#eef2f7', padding: '15px', borderRadius: '8px', marginBottom: '15px' }}>
        <h3>1 & 2. Class Output:</h3>
        <p><strong>Introduce:</strong> {student.introduce()}</p>
        <p><strong>Full Info:</strong> {student.getStudentInfo()}</p>
      </div>

      {/* 4. Destructuring */}
      <div style={{ background: '#fff3cd', padding: '15px', borderRadius: '8px', marginBottom: '15px' }}>
        <h3>4. Destructuring Output:</h3>
        <p>Name: <strong>{name}</strong> | Age: <strong>{age}</strong></p>
      </div>

      {/* 5. Spread Operator Form */}
      <form onSubmit={handleAddScore} style={{ marginBottom: '15px' }}>
        <h3>5. Add Score (Spread Operator):</h3>
        <div style={{ display: 'flex', gap: '10px' }}>
          <input
            type="number"
            step="0.5"
            placeholder="Nhập điểm mới"
            value={inputScore}
            onChange={(e) => setInputScore(e.target.value)}
            style={{ flex: 1, padding: '8px' }}
          />
          <button type="submit" style={{ padding: '8px 16px', background: '#28a745', color: '#fff', border: 'none', borderRadius: '4px' }}>
            Add
          </button>
        </div>
      </form>

      {/* 6. Array Methods */}
      <div style={{ background: '#f8f9fa', padding: '15px', borderRadius: '8px', marginBottom: '15px' }}>
        <h3>6. Array Methods Demo:</h3>
        <ul>
          <li><strong>Scores:</strong> [{scores.join(', ')}]</li>
          <li><strong>filter() (Passing &ge; 5):</strong> [{passingScores.join(', ')}]</li>
          <li><strong>map():</strong> {formattedScores.join(' - ')}</li>
          <li><strong>reduce() (Total Sum):</strong> {totalScore}</li>
        </ul>
      </div>

      {/* 7. Promise */}
      <div style={{ background: evaluation === 'Excellent Student' ? '#d4edda' : '#f8d7da', padding: '15px', borderRadius: '8px' }}>
        <h3>7. Academic Evaluation (Promise):</h3>
        <p style={{ fontSize: '18px', fontWeight: 'bold', margin: 0 }}>
          Result: {evaluation}
        </p>
      </div>
    </div>
  );
}
